#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""regex_engine: a small backtracking-free regular expression engine.

Public API (mirrors the subset of ``re`` used by the grader):

    regex_engine.compile(pattern) -> Pattern
    regex_engine.match(pattern, text) -> Match | None
    regex_engine.search(pattern, text) -> Match | None

The pattern is parsed into an AST and compiled to a Thompson NFA.  Matching
uses a Pike-style simulation: at each text position we keep a set of active
NFA threads, each carrying its own capture snapshot.  Because a thread is
identified only by its NFA state (duplicates are merged), the simulation is
linear in the text length even for patterns with nested quantifiers such as
``(a+)+$`` that defeat naive backtracking.

Only the Python standard library is used.
"""


class _Match:
    __slots__ = ("re", "string", "_caps")

    def __init__(self, pattern, string, caps):
        self.re = pattern
        self.string = string
        self._caps = caps

    def span(self, group=0):
        v = self._caps.get(group)
        if v is None:
            return (-1, -1)
        return v

    def start(self, group=0):
        return self.span(group)[0]

    def end(self, group=0):
        return self.span(group)[1]

    def group(self, *groups):
        if not groups:
            groups = (0,)
        if len(groups) == 1:
            g = groups[0]
            if g is None:
                g = 0
            s, e = self.span(g)
            if s < 0:
                return None
            return self.string[s:e]
        return tuple(self.group(g) for g in groups)

    def groups(self):
        out = []
        for i in range(1, self.re.groups + 1):
            s, e = self.span(i)
            out.append(None if s < 0 else self.string[s:e])
        return tuple(out)

    def __repr__(self):
        s, e = self.span()
        return "<%s object; span=(%d, %d), match=%r>" % (
            type(self).__name__, s, e, self.string[s:e])


class Pattern:
    def __init__(self, pattern, groups, prog):
        self.pattern = pattern
        self.groups = groups
        self._prog = prog

    def match(self, text, pos=0):
        if pos < 0 or pos > len(text):
            raise ValueError("pos out of range")
        return self._prog.match(text, pos, anchored=True)

    def search(self, text, pos=0):
        if pos < 0 or pos > len(text):
            raise ValueError("pos out of range")
        return self._prog.match(text, pos, anchored=False)

    def __repr__(self):
        return "regex_engine.compile(%r)" % (self.pattern,)


# ---------------------------------------------------------------------------
# Parser: pattern string -> AST
# ---------------------------------------------------------------------------

_DIGIT = frozenset("0123456789")
_WORD = frozenset("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_")
_SPACE = frozenset(" \t\n\r\f\v")


class _Parser:
    def __init__(self, pattern):
        self.s = pattern
        self.i = 0
        self.n = len(pattern)
        self.ngroups = 0

    def parse(self):
        node = self.parse_alt()
        if self.i != self.n:
            raise ValueError("unbalanced parenthesis at position %d" % self.i)
        return node

    def parse_alt(self):
        branches = [self.parse_concat()]
        while self.i < self.n and self.s[self.i] == "|":
            self.i += 1
            branches.append(self.parse_concat())
        if len(branches) == 1:
            return branches[0]
        return ("alt", branches)

    def parse_concat(self):
        items = []
        while self.i < self.n and self.s[self.i] not in ")|":
            items.append(self.parse_repeat())
        if not items:
            return ("empty",)
        node = items[0]
        for nxt in items[1:]:
            node = ("cat", node, nxt)
        return node

    def parse_repeat(self):
        atom = self.parse_atom()
        while self.i < self.n and self.s[self.i] in "*+?{":
            ch = self.s[self.i]
            if ch == "{":
                saved = self.i
                self.i += 1
                lo = self._read_int()
                if lo is None:
                    self.i = saved
                    break
                hi = lo
                if self.i < self.n and self.s[self.i] == ",":
                    self.i += 1
                    hv = self._read_int()
                    hi = hv if hv is not None else -1
                if self.i >= self.n or self.s[self.i] != "}":
                    self.i = saved
                    break
                self.i += 1
                atom = ("rep", atom, lo, hi, False)
            else:
                self.i += 1
                if ch == "*":
                    lo, hi = 0, -1
                elif ch == "+":
                    lo, hi = 1, -1
                else:
                    lo, hi = 0, 1
                atom = ("rep", atom, lo, hi, False)
            if self.i < self.n and self.s[self.i] == "?":
                self.i += 1
                atom = ("rep", atom[1], atom[2], atom[3], True)
        return atom

    def _read_int(self):
        j = self.i
        while j < self.n and self.s[j] in _DIGIT:
            j += 1
        if j == self.i:
            return None
        v = int(self.s[self.i:j])
        self.i = j
        return v

    def parse_atom(self):
        ch = self.s[self.i]
        if ch == "(":
            self.i += 1
            gid = self.ngroups
            self.ngroups += 1
            body = self.parse_alt()
            if self.i >= self.n or self.s[self.i] != ")":
                raise ValueError("missing )")
            self.i += 1
            return ("group", gid, body)
        if ch == "[":
            self.i += 1
            return self.parse_class()
        if ch == ".":
            self.i += 1
            return ("char", _DOT, False)
        if ch == "^":
            self.i += 1
            return ("bol",)
        if ch == "$":
            self.i += 1
            return ("eol",)
        if ch == "\\":
            self.i += 1
            if self.i >= self.n:
                raise ValueError("bad escape at end of pattern")
            e = self.s[self.i]
            self.i += 1
            if e == "d":
                return ("char", _DIGIT, False)
            if e == "D":
                return ("char", _DIGIT, True)
            if e == "w":
                return ("char", _WORD, False)
            if e == "W":
                return ("char", _WORD, True)
            if e == "s":
                return ("char", _SPACE, False)
            if e == "S":
                return ("char", _SPACE, True)
            if e == "n":
                return ("lit", "\n")
            if e == "t":
                return ("lit", "\t")
            if e == "r":
                return ("lit", "\r")
            return ("lit", e)
        self.i += 1
        return ("lit", ch)

    def parse_class(self):
        negated = False
        if self.i < self.n and self.s[self.i] == "^":
            negated = True
            self.i += 1
        members = []
        first = True
        while first or (self.i < self.n and self.s[self.i] != "]"):
            first = False
            if self.i >= self.n:
                raise ValueError("unterminated character class")
            members.append(self._class_atom())
        if self.i >= self.n:
            raise ValueError("unterminated character class")
        self.i += 1  # ]
        s = set()
        for m in members:
            if m[0] == "set":
                s |= m[1]
            elif m[0] == "range":
                lo, hi = m[1], m[2]
                if lo > hi:
                    raise ValueError("bad character range %r-%r" % (lo, hi))
                s |= {chr(c) for c in range(ord(lo), ord(hi) + 1)}
            else:
                s.add(m[1])
        return ("char", frozenset(s), negated)

    def _class_atom(self):
        ch = self._class_char()
        if (self.i + 1 < self.n and self.s[self.i] == "-"
                and self.s[self.i + 1] != "]"):
            self.i += 1  # -
            hi = self._class_char()
            return ("range", ch, hi)
        if isinstance(ch, frozenset):
            return ("set", ch)
        return ("lit", ch)

    def _class_char(self):
        ch = self.s[self.i]
        if ch == "\\":
            self.i += 1
            e = self.s[self.i]
            self.i += 1
            simple = {
                "d": _DIGIT, "D": _DIGIT, "w": _WORD, "W": _WORD,
                "s": _SPACE, "S": _SPACE,
                "n": "\n", "t": "\t", "r": "\r",
            }
            return simple.get(e, e)
        self.i += 1
        return ch


_DOT = frozenset()  # empty set is the sentinel for "any except newline"


# ---------------------------------------------------------------------------
# Compiler: AST -> Thompson NFA
# ---------------------------------------------------------------------------

class _NFA:
    def __init__(self):
        self.frag = []  # list of dict(action -> list of state indices)
        self.match = self._new()

    def _new(self):
        self.frag.append({})
        return len(self.frag) - 1

    def _edge(self, st, action, to):
        self.frag[st].setdefault(action, []).append(to)

    def _epsilon(self, st, to):
        self._edge(st, "", to)

    def build(self, node):
        start = self._emit(node)
        self._epsilon(start, self.match)
        return 0  # state 0 is always the entry of the emitted top fragment

    def _emit(self, node):
        kind = node[0]
        if kind == "empty":
            return self._new()
        if kind == "lit":
            return self._char_state(("lit", node[1]))
        if kind == "char":
            return self._char_state(("set", node[1], node[2]))
        if kind == "bol":
            return self._char_state(("bol",))
        if kind == "eol":
            return self._char_state(("eol",))
        if kind == "cat":
            a = self._emit(node[1])
            b = self._emit(node[2])
            split = self._new()
            self._epsilon(split, a)
            self._edge(split, ("jmp", b), b)
            return split
        if kind == "alt":
            split = self._new()
            for branch in node[1]:
                self._epsilon(split, self._emit(branch))
            return split
        if kind == "group":
            _, gid, body = node
            open_st = self._char_state(("cap", gid * 2))
            inner = self._emit(body)
            close_st = self._char_state(("cap", gid * 2 + 1))
            s1 = self._new()
            self._epsilon(s1, open_st)
            self._edge(s1, ("jmp", inner), inner)
            s2 = self._new()
            self._epsilon(s2, inner)
            self._edge(s2, ("jmp", close_st), close_st)
            return s1
        if kind == "rep":
            return self._emit_rep(node[1], node[2], node[3], node[4])
        raise ValueError("bad ast node %r" % (node,))

    def _char_state(self, action):
        st = self._new()
        self._edge(st, action, self._new())
        return st

    def _emit_rep(self, atom_ast, lo, hi, lazy):
        entry = self._new()
        cur = entry
        inf = hi < 0
        total_hi = None if inf else hi

        def emit_copy():
            st = self._emit(atom_ast)
            out = self._new()
            self._epsilon(out, st)
            return out

        copies = []
        for _ in range(lo):
            c = emit_copy()
            copies.append(c)
            self._epsilon(cur, c)
            cur = c
        if inf:
            body = emit_copy()
            lp = self._new()
            self._epsilon(cur, lp)
            self._epsilon(lp, body)
            cont = self._new()
            if lazy:
                self._edge(lp, ("jmp", cont), cont)
            else:
                self._epsilon(lp, cont)
            after = self._new()
            self._epsilon(cont, after)
            if lazy:
                self._epsilon(lp, after)
            else:
                self._edge(lp, ("jmp", after), after)
            self._epsilon(body, lp)
            return entry
        extra = hi - lo
        finals = [cur]
        for _ in range(extra):
            c = emit_copy()
            copies.append(c)
            split = self._new()
            self._epsilon(cur, split)
            if lazy:
                self._edge(split, ("jmp", c), c)
            else:
                self._epsilon(split, c)
            cur = c
            finals.append(split)
        join = self._new()
        for f in finals:
            self._epsilon(f, join)
        return entry


# ---------------------------------------------------------------------------
# Pike VM simulation
# ---------------------------------------------------------------------------

