#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""A small regex engine: Thompson NFA + Pike VM (linear-time simulation).

Public API:
    compile(pattern) -> Pattern
    match(pattern, text) -> Match | None   (anchored at start)
    search(pattern, text) -> Match | None  (leftmost match)

Supported syntax:
    literals, . , [...] / [^...], \\d \\D \\w \\W \\s \\S, \\n \\t \\r escapes,
    * + ? {m} {m,} {m,n} and lazy variants, (...) groups, | alternation,
    ^ $ anchors ($ matches at end or before a trailing newline).

Only the standard library is used; the `re` module is never imported.
"""


class _RegexError(Exception):
    pass


# ---------------------------------------------------------------- parser ----

# Node types:
# ('empty',)            matches epsilon
# ('char', fn)          fn(c) -> bool
# ('any',)              any char except newline
# ('anchor', kind)      kind in ('^', '$')
# ('cat', a, b)
# ('alt', a, b)
# ('rep', a, lo, hi, greedy)   hi is int or float('inf')
# ('group', gid, a)     capture group wrapper (gid 0 = whole match allowed)


def _char_eq(ch):
    return lambda c, ch=ch: c == ch


_DIGIT = lambda c: c.isdigit()
_WORD = lambda c: c.isalnum() or c == '_'
_SPACE = lambda c: c in " \t\n\r\f\v"


def _neg(fn):
    return lambda c, fn=fn: not fn(c)


def _class_fn(negated, members):
    """members: list of bool-functions over a single char."""
    def pred(c):
        for m in members:
            if m(c):
                return not negated
        return negated
    return pred


def _range_fn(lo, hi):
    return lambda c, lo=lo, hi=hi: lo <= c <= hi


class _Parser:
    def __init__(self, pattern):
        self.s = pattern
        self.i = 0
        self.ngroups = 0  # number of explicit groups seen

    # -- primitives -----------------------------------------------------

    def parse(self):
        node = self.parse_alt()
        if self.i != len(self.s):
            raise _RegexError("unexpected %r at %d" % (self.s[self.i], self.i))
        return node, self.ngroups

    def parse_alt(self):
        node = self.parse_concat()
        while self.i < len(self.s) and self.s[self.i] == '|':
            self.i += 1
            rhs = self.parse_concat()
            node = ('alt', node, rhs)
        return node

    def parse_concat(self):
        seq = []
        while self.i < len(self.s) and self.s[self.i] not in ')|':
            seq.append(self.parse_quant())
        if not seq:
            return ('empty',)
        node = seq[0]
        for n in seq[1:]:
            node = ('cat', node, n)
        return node

    def parse_quant(self):
        node = self.parse_atom()
        while self.i < len(self.s) and self.s[self.i] in '*+?{':
            ch = self.s[self.i]
            if ch == '{':
                saved = self.i
                mlo, mhi, ok = self._try_brace()
                if not ok:
                    self.i = saved
                    break
                greedy = self._greedy_flag()
                node = ('rep', node, mlo, mhi, greedy)
            else:
                self.i += 1
                if ch == '*':
                    lo, hi = 0, float('inf')
                elif ch == '+':
                    lo, hi = 1, float('inf')
                else:
                    lo, hi = 0, 1
                greedy = self._greedy_flag()
                node = ('rep', node, lo, hi, greedy)
        return node

    def _greedy_flag(self):
        if self.i < len(self.s) and self.s[self.i] == '?':
            self.i += 1
            return False
        return True

    def _try_brace(self):
        # Assumes s[i] == '{'. Returns (lo, hi, ok).
        j = self.i + 1
        n = len(self.s)
        start = j
        while j < n and self.s[j].isdigit():
            j += 1
        lo_str = self.s[start:j]
        hi_str = None
        if j < n and self.s[j] == '}':
            if not lo_str:
                return 0, 0, False
            j += 1
            v = int(lo_str)
            self.i = j
            return v, v, True
        if j < n and self.s[j] == ',':
            j += 1
            hstart = j
            while j < n and self.s[j].isdigit():
                j += 1
            hi_str = self.s[hstart:j]
            if j < n and self.s[j] == '}':
                if not lo_str and not hi_str:
                    return 0, 0, False
                lo = int(lo_str) if lo_str else 0
                hi = int(hi_str) if hi_str else float('inf')
                j += 1
                self.i = j
                return lo, hi, True
        return 0, 0, False

    def parse_atom(self):
        ch = self.s[self.i]
        if ch == '(':
            self.i += 1
            self.ngroups += 1
            gid = self.ngroups
            inner = self.parse_alt()
            if self.i >= len(self.s) or self.s[self.i] != ')':
                raise _RegexError("missing )")
            self.i += 1
            return ('group', gid, inner)
        if ch == '[':
            self.i += 1
            return self.parse_class()
        if ch == '.':
            self.i += 1
            return ('any',)
        if ch == '^':
            self.i += 1
            return ('anchor', '^')
        if ch == '$':
            self.i += 1
            return ('anchor', '$')
        if ch == '\\':
            self.i += 1
            return self.parse_escape(in_class=False)
        self.i += 1
        return ('char', _char_eq(ch))

    def parse_escape(self, in_class):
        if self.i >= len(self.s):
            raise _RegexError("dangling backslash")
        ch = self.s[self.i]
        self.i += 1
        simple = {
            'n': ('char', _char_eq('\n')),
            't': ('char', _char_eq('\t')),
            'r': ('char', _char_eq('\r')),
            'f': ('char', _char_eq('\f')),
            'v': ('char', _char_eq('\v')),
            '0': ('char', _char_eq('\0')),
            'd': ('char', _DIGIT),
            'D': ('char', _neg(_DIGIT)),
            'w': ('char', _WORD),
            'W': ('char', _neg(_WORD)),
            's': ('char', _SPACE),
            'S': ('char', _neg(_SPACE)),
        }
        if ch in simple:
            return simple[ch]
        return ('char', _char_eq(ch))

    def parse_class(self):
        negated = False
        if self.i < len(self.s) and self.s[self.i] == '^':
            negated = True
            self.i += 1
        members = []
        first = True
        n = len(self.s)
        while self.i < n and (first or self.s[self.i] != ']'):
            first = False
            # member: possibly an escape, possibly a range
            lo_node = self._class_single()
            if (self.i + 1 < n and self.s[self.i] == '-'
                    and self.s[self.i + 1] != ']'):
                self.i += 1  # consume '-'
                hi_node = self._class_single()
                if lo_node[0] != 'lit' or hi_node[0] != 'lit':
                    raise _RegexError("bad character range")
                members.append(_range_fn(lo_node[1], hi_node[1]))
            else:
                if lo_node[0] == 'lit':
                    members.append(_char_eq(lo_node[1]))
                else:
                    members.append(lo_node[1])
        if self.i >= n:
            raise _RegexError("unterminated character class")
        self.i += 1  # consume ']'
        return ('char', _class_fn(negated, members))

    def _class_single(self):
        """One element inside a class. Returns ('lit', ch) or ('pred', fn)."""
        ch = self.s[self.i]
        if ch == '\\':
            self.i += 1
            if self.i >= len(self.s):
                raise _RegexError("dangling backslash in class")
            e = self.s[self.i]
            self.i += 1
            specials = {
                'd': _DIGIT, 'D': _neg(_DIGIT),
                'w': _WORD, 'W': _neg(_WORD),
                's': _SPACE, 'S': _neg(_SPACE),
                'n': _char_eq('\n'), 't': _char_eq('\t'),
                'r': _char_eq('\r'), 'f': _char_eq('\f'), 'v': _char_eq('\v'),
                '0': _char_eq('\0'),
            }
            if e in specials:
                return ('pred', specials[e])
            return ('lit', e)
        self.i += 1
        return ('lit', ch)


# ------------------------------------------------------------- NFA build ----

class _State:
    __slots__ = ('outs',)

    def __init__(self):
        self.outs = []  # list of (target_state_id, kind, data)


# Arc kinds:
#   'e'   epsilon, data None
#   'c'   consume, data = predicate fn
#   'g'   group open epsilon, data = gid
#   'h'   group close epsilon, data = gid
#   '^'   anchor start
#   '$'   anchor end (end or before trailing \n)


class _NFA:
    def __init__(self):
        self.states = []

    def new(self):
        self.states.append(_State())
        return len(self.states) - 1

    def arc(self, src, dst, kind='e', data=None):
        self.states[src].outs.append((dst, kind, data))


def _build(node, nfa):
    """Return (start, accept) state ids for node."""
    t = node[0]
    if t == 'empty':
        s = nfa.new()
        a = nfa.new()
        nfa.arc(s, a)
        return s, a
    if t in ('char', 'any'):
        s = nfa.new()
        a = nfa.new()
        if t == 'char':
            nfa.arc(s, a, 'c', node[1])
        else:
            nfa.arc(s, a, 'c', lambda c: c != '\n')
        return s, a
    if t == 'anchor':
        s = nfa.new()
        a = nfa.new()
        nfa.arc(s, a, node[1])
        return s, a
    if t == 'cat':
        s1, a1 = _build(node[1], nfa)
        s2, a2 = _build(node[2], nfa)
        nfa.arc(a1, s2)
        return s1, a2
    if t == 'alt':
