#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""A small regular expression engine (Thompson NFA + Pike VM).

Public API mirrors a subset of Python's ``re``:

    compile(pattern)          -> Pattern, with .match(text)/.search(text)
    match(pattern, text)      -> Match | None
    search(pattern, text)     -> Match | None

Supported syntax: literals, ``.``, ``[...]`` / ``[^...]``, ``\\d \\D \\w
\\s \\S``, ``\\n \\t \\r``, ``* + ? {m} {m,} {m,n}`` (with lazy variants),
``(...)`` groups, ``|`` alternation, ``^`` / ``$`` anchors.

A Pike virtual machine runs the NFA: at every input position a set of threads
is tracked, each carrying capture indices; threads arriving at an
already-active NFA state are merged (earliest thread wins, giving
leftmost-first POSIX-like semantics used by Python ``re``). Work is
O(text * states), so ``(a+)+$`` against 10**5 characters stays linear.
"""


class _Node(object):
    __slots__ = ("kind", "out", "out2", "ch", "pred", "cap", "anchor", "lazy")

    def __init__(self, kind):
        self.kind = kind       # 'c' char, '.' any, 'cls' class, 'e' epsilon,
                               # 's' split(pref out then out2), 'm' match,
                               # 'cap' group boundary, 'anc' anchor
        self.out = None
        self.out2 = None
        self.ch = None
        self.pred = None       # ('class', chars:frozenset, cats:str, neg:bool)
        self.cap = None        # (gid, is_close)
        self.anchor = None     # '^' or '$'
        self.lazy = False      # split preference swapped for lazy quantifiers


class _Frag(object):
    __slots__ = ("start", "ends")

    def __init__(self, start, ends):
