# --------------------------- Pike VM execution ---------------------------

def _class_match(node, ch):
    ok = ch in node.chars
    cats = node.cats
    if not ok and cats:
        for e in cats:
            if e == 'd':
                ok = ch in DIGIT_CHARS
            elif e == 'D':
                ok = ch not in DIGIT_CHARS
            elif e == 'w':
                ok = ch in WORD_CHARS
            elif e == 'W':
                ok = ch not in WORD_CHARS
            elif e == 's':
                ok = ch in SPACE_CHARS
            elif e == 'S':
                ok = ch not in SPACE_CHARS
            if ok:
                break
    return (not ok) if node.neg else ok


def _char_ok(node, ch, pos, text):
    k = node.kind
    if k == 'c':
        return node.ch == ch
    if k == '.':
        return ch != '\n'
    if k == 'cl':
        return _class_match(node, ch)
    return False


def _number_nodes(start):
    """Assign integer ids to every reachable node."""
    num = 0
