# ------------------------------ Public API -------------------------------

class Match(object):
    def __init__(self, text, pos, caps, ngroups):
        self._text = text
        self._base = pos
        self._caps = caps
        self._ng = ngroups

    def span(self, group=0):
        i = group * 2
        a, b = self._caps[i], self._caps[i + 1]
        if a < 0:
            return (-1, -1)
        return (a, b)

    def start(self, group=0):
        return self.span(group)[0]

    def end(self, group=0):
        return self.span(group)[1]

    def group(self, group=0):
        a, b = self.span(group)
        if a < 0:
            return None
        return self._text[a:b]

    def groups(self):
        out = []
        for g in range(1, self._ng):
            a, b = self.span(g)
            out.append(None if a < 0 else self._text[a:b])
        return tuple(out)

    def __repr__(self):
        return "<regex_engine.Match object; span=%r, match=%r>" % (
            self.span(), self.group())


class Pattern(object):
    def __init__(self, pattern):
        self.pattern = pattern
        parser = _Parser(pattern)
        self._start, self._ng = parser.parse()
        self._nstates = _number_nodes(self._start)

