        caps = _execute(self._start, self._nstates, self._ng, text, anchored)
        if caps is None:
            return None
        return Match(text, 0, caps, self._ng)

    def match(self, text):
        return self._do(text, True)

    def search(self, text):
        return self._do(text, False)


def compile(pattern):
    return Pattern(pattern)


